import csv
import hashlib

def authenticate_user(username, password, csv_file='employees.csv'):
    """
    Authenticate user against employee credentials stored in CSV.
    CSV format: username,password_hash
    """
    with open(csv_file, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row['username'] == username:
                # Hash the input password and compare
                input_hash = hashlib.md5(password.encode()).hexdigest()
                if input_hash == row['password_hash']:
                    return True
                else:
                    return False
        return False

def load_credentials(csv_file='employees.csv'):
    """Load all credentials into memory for faster lookups."""
    credentials = {}
    with open(csv_file, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            credentials[row['username']] = row['password_hash']
    return credentials

# Simple lookup authentication
creds = load_credentials()
if creds.get('john.doe') == hashlib.md5('mypassword'.encode()).hexdigest():
    print('Authentication successful')
else:
    print('Authentication failed')
